"use client"

import * as React from "react"

import { Meter } from "@/registry/preskok/ui/preskok-ui/meter"
import { ProgressBar } from "@/registry/preskok/ui/preskok-ui/progress-bar"

export default function ProgressDemo() {
  const [progress, setProgress] = React.useState(13)
  const [mounted, setMounted] = React.useState(false)

  React.useEffect(() => {
    setMounted(true)
    const timer = setTimeout(() => setProgress(66), 500)
    return () => clearTimeout(timer)
  }, [])

  if (!mounted) {
    return (
      <div className="w-full max-w-sm space-y-4">
        <div className="bg-muted h-16 w-full animate-pulse rounded" />
        <div className="bg-muted h-8 w-full animate-pulse rounded" />
      </div>
    )
  }

  return (
    <div className="w-full max-w-sm space-y-4">
      <Meter label="Storage" value={66} minValue={0} maxValue={100} />
      <ProgressBar label="Uploading" value={66} />
    </div>
  )
}
